const readline = require('readline');

function gcd(a, b) {
    if (b === 0) return a;
    return gcd(b, a % b);
}

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    const [a, b, x, y] = input.split(' ').map(Number);

    const d = gcd(x, y);
    x /= d;
    y /= d;

    const k1 = Math.floor(a / x);
    const k2 = Math.floor(b / y);
    const k = Math.min(k1, k2);

    console.log(`${x * k} ${y * k}`);
    rl.close();
});

